import React from 'react';
import { Link, useLocation, useNavigate } from 'react-router-dom';

const OrderSuccessPage = () => {
  const location = useLocation();
  const navigate = useNavigate();
  const order = location.state?.order;

  if (!order) { navigate('/'); return null; }

  const printInvoice = () => {
    const invoiceHTML = `
      <html><head><title>Invoice - ${order.invoiceNumber}</title>
      <style>
        body { font-family: Arial; padding: 30px; max-width: 600px; margin: 0 auto; }
        h1 { color: #16a34a; } table { width: 100%; border-collapse: collapse; }
        th, td { padding: 10px; text-align: left; border-bottom: 1px solid #eee; }
        th { background: #f0fdf4; } .total { font-size: 20px; font-weight: bold; }
        .green { color: #16a34a; }
      </style></head>
      <body>
        <h1>🌿 Desi2Door</h1>
        <p style="color:#999">Fresh From Farm to Doorstep</p>
        <hr/>
        <h2>Invoice: ${order.invoiceNumber}</h2>
        <p><strong>Date:</strong> ${new Date(order.createdAt).toLocaleDateString('en-IN', { dateStyle: 'long' })}</p>
        <p><strong>Delivery Slot:</strong> ${order.deliverySlot || 'As scheduled'}</p>
        <h3>Customer Details:</h3>
        <p>${order.customerName}<br/>${order.customerPhone}<br/>${order.customerEmail || ''}</p>
        <p><strong>Delivery Address:</strong><br/>${order.address.street}, ${order.address.city}, ${order.address.state} - ${order.address.pincode}</p>
        <h3>Items Ordered:</h3>
        <table>
          <tr><th>#</th><th>Item</th><th>Qty</th><th>Price</th><th>Total</th></tr>
          ${order.items.map((item, i) => `<tr><td>${i+1}</td><td>${item.name}</td><td>${item.quantity}</td><td>₹${item.price}</td><td>₹${item.price * item.quantity}</td></tr>`).join('')}
        </table>
        <br/>
        <p class="total green">Grand Total: ₹${order.totalAmount}</p>
        <p><strong>Payment:</strong> Cash on Delivery</p>
        <p><strong>Status:</strong> ${order.status}</p>
        <hr/>
        <p style="color:#999;font-size:12px">Thank you for shopping with Desi2Door! Contact: support@desi2door.com</p>
      </body></html>
    `;
    const win = window.open('', '_blank');
    win.document.write(invoiceHTML);
    win.document.close();
    win.print();
  };

  return (
    <div className="page-fade" style={{ minHeight: '80vh', display: 'flex', alignItems: 'center' }}>
      <div className="container" style={{ maxWidth: 640, margin: '0 auto', padding: '40px 16px', textAlign: 'center' }}>
        {/* Success Icon */}
        <div style={{ width: 100, height: 100, background: 'var(--green-bg)', borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center', margin: '0 auto 24px', fontSize: 50 }}>
          ✅
        </div>
        <h1 style={{ fontFamily: 'var(--font-display)', fontSize: 34, color: 'var(--green)', marginBottom: 8 }}>
          Order Placed! 🎉
        </h1>
        <p style={{ color: 'var(--gray-600)', fontSize: 18, marginBottom: 8 }}>
          Thank you, <strong>{order.customerName}</strong>!
        </p>
        <p style={{ color: 'var(--gray-400)', fontSize: 15, marginBottom: 32 }}>
          Your order is confirmed. Our team will prepare and deliver it fresh!
        </p>

        {/* Order Card */}
        <div style={{ background: 'white', borderRadius: 20, padding: 24, boxShadow: '0 4px 20px rgba(0,0,0,0.08)', marginBottom: 24, textAlign: 'left' }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 16, flexWrap: 'wrap', gap: 8 }}>
            <div>
              <div style={{ fontSize: 12, color: 'var(--gray-400)', fontWeight: 600 }}>ORDER ID</div>
              <div style={{ fontFamily: 'var(--font-display)', fontWeight: 700, fontSize: 16, color: 'var(--green)' }}>{order.invoiceNumber}</div>
            </div>
            <div style={{ textAlign: 'right' }}>
              <div style={{ fontSize: 12, color: 'var(--gray-400)', fontWeight: 600 }}>STATUS</div>
              <span style={{ background: 'var(--orange-bg)', color: 'var(--orange)', fontWeight: 700, fontSize: 14, padding: '3px 12px', borderRadius: 20 }}>
                {order.status}
              </span>
            </div>
          </div>

          <div style={{ borderTop: '1px solid var(--gray-100)', paddingTop: 16, marginBottom: 16 }}>
            <div style={{ fontSize: 13, fontWeight: 600, color: 'var(--gray-600)', marginBottom: 8 }}>📍 Delivery to:</div>
            <div style={{ fontSize: 14, color: 'var(--gray-700)' }}>
              {order.address.street}, {order.address.city}, {order.address.state} - {order.address.pincode}
            </div>
            {order.deliverySlot && <div style={{ fontSize: 13, color: 'var(--green-dark)', fontWeight: 600, marginTop: 6 }}>⏰ Slot: {order.deliverySlot}</div>}
          </div>

          <div style={{ borderTop: '1px solid var(--gray-100)', paddingTop: 16 }}>
            <div style={{ fontSize: 13, fontWeight: 600, color: 'var(--gray-600)', marginBottom: 10 }}>🛒 Items Ordered:</div>
            {order.items.map((item, i) => (
              <div key={i} style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 6, fontSize: 14 }}>
                <span style={{ color: 'var(--gray-700)' }}>{item.name} × {item.quantity}</span>
                <span style={{ fontWeight: 600 }}>₹{item.price * item.quantity}</span>
              </div>
            ))}
            <div style={{ borderTop: '2px solid var(--gray-100)', paddingTop: 10, marginTop: 10, display: 'flex', justifyContent: 'space-between' }}>
              <span style={{ fontFamily: 'var(--font-display)', fontWeight: 800, fontSize: 18 }}>Total Amount</span>
              <span style={{ fontFamily: 'var(--font-display)', fontWeight: 800, fontSize: 22, color: 'var(--green)' }}>₹{order.totalAmount}</span>
            </div>
          </div>

          <div style={{ background: 'var(--orange-bg)', borderRadius: 10, padding: '10px 14px', marginTop: 16, fontSize: 14, color: 'var(--orange)', fontWeight: 600 }}>
            💳 Cash on Delivery — Pay ₹{order.totalAmount} when you receive your order
          </div>
          {order.whatsappNotified && (
            <div style={{ background: '#f0fff4', borderRadius: 10, padding: '10px 14px', marginTop: 8, fontSize: 13, color: '#166534' }}>
              ✅ WhatsApp notification sent to retailer
            </div>
          )}
        </div>

        <div style={{ display: 'flex', gap: 12, justifyContent: 'center', flexWrap: 'wrap' }}>
          <button onClick={printInvoice} className="btn-outline">
            🖨️ Print Invoice
          </button>
          <Link to="/orders" className="btn-primary">📦 View My Orders</Link>
          <Link to="/shop" className="btn-orange">🛒 Continue Shopping</Link>
        </div>
      </div>
    </div>
  );
};

export default OrderSuccessPage;
